  // A MAUI head lists the RIDs of its other targets too (maccatalyst, ios): only the windows ones are packaged here.
  const wanted = maui ? listed.filter(r => /^win-/.test(r)) : listed;
  const runtimes = (wanted.length ? wanted : [machineRid()]).map(rid => ({ rid, args: ['-r', rid, '--self-contained'] }));
