  const lines = [`# v${version}`, '', ...(glossary ? ['Technical terms: [glossary](../glossary.md)', ''] : []), previous ?`Since ${previous}.` : 'First release.', ''];
  if (!items.length && !other.length) lines.push('No merges on the main branch since then.', '');
  if (items.length) lines.push('## Items', '', ...items, '');
