// BR15: the Aspire packages of the AppHost carry the version of `aspire --version`, or the CLI cannot reach the AppHost it starts.
function aspireMismatch(dir, command) {
  const given = (/--apphost\s+("[^"]+"|\S+)/.exec(command) || [])[1];
  if (!given) return null;
  const apphost = path.resolve(dir, given.replace(/"/g, ''));
  const files = [apphost];
  for (let d = path.dirname(apphost); ; d = path.dirname(d)) {
    for (const f of ['Directory.Packages.props', 'Directory.Build.props']) if (fs.existsSync(path.join(d, f))) files.push(path.join(d, f));
    if (path.resolve(d) === path.resolve(dir) || path.dirname(d) === d) break;
  }
  const found = [];
  for (const f of files) {
    const text = projectText(f);
    for (const tagMatch of text.matchAll(/<[^>]*(?:Include|Update|Name)="(Aspire\.AppHost\.Sdk|Aspire\.Hosting[\w.]*)"[^>]*>/g)) {
      const v = (/\bVersion="([^"]+)"/.exec(tagMatch[0]) || [])[1];
      if (v && !v.includes('$(')) found.push({ name: tagMatch[1], version: v, file: forward(path.relative(dir, f)) });
    }
    for (const sdk of text.matchAll(/Sdk="Aspire\.AppHost\.Sdk\/([^"]+)"/g)) if (!sdk[1].includes('$(')) found.push({ name: 'Aspire.AppHost.Sdk', version: sdk[1], file: forward(path.relative(dir, f)) });
  }
  const cli = (process.env.AGILE_ASPIRE_VERSION || run('aspire', ['--version']).stdout.split('\n')[0] || '').trim().replace(/\+.*$/, '');
  if (!cli) return 'the `aspire` CLI is not installed or does not answer `aspire --version`: install it (https://aspire.dev) and run the command again; nothing ran';
  const wrong = found.filter(f => f.version !== cli);
  if (!wrong.length) return null;
  return `the Aspire CLI is ${cli} but ${wrong.map(w => `${w.name} is ${w.version} (${w.file})`).join(', ')}: they must match. Update the CLI to ${wrong[0].version} (aspire update --self), or set the packages to ${cli}; nothing ran`;
}

const sleep = ms => new Promise(r => setTimeout(r, ms));
// BR7: poll the Check URL until it answers 200, for at most `seconds`.
async function pollCheck(url, seconds) {
  const started = Date.now();
  let last = 'no answer';
  while ((Date.now() - started) / 1000 < seconds) {
    try {
      const res = await fetch(url, { signal: AbortSignal.timeout(5000), redirect: 'manual' });
      if (res.status === 200) return { ok: true, status: 200, seconds: Math.round((Date.now() - started) / 100) / 10 };
      last = `HTTP ${res.status}`;
    } catch (e) { last = (e.cause && e.cause.code) || e.name || 'no answer'; }
    await sleep(1000);
  }
  return { ok: false, last, seconds };
}

// A CLI's colors and hyperlinks (CSI and OSC 8 sequences) are noise in a report; the saved log keeps them.
