  const lines = text.split('\n'), table = sectionTable(lines, 'Environments');
  if (!table) return done({ ...out, stop: ['docs/infra.md has no `## Environments` table'] });
  if (table.badRow) return done({ ...out, stop: [table.badRow] });
  const [cEnv, cCmd, cCheck] = [columnOf(table, 'environment'), columnOf(table, 'deploy command'), columnOf(table, 'check url')];
  const known = table.rows.map(r => r.cells[cEnv]).filter(Boolean);
  const row = table.rows.find(r => (r.cells[cEnv] || '').toLowerCase() === environment.toLowerCase());
  if (!row) return done({ ...out, stop: [`docs/infra.md has no environment "${environment}" (it has: ${known.join(', ')})`] });
  const command = cCmd >= 0 ? unquote(row.cells[cCmd] || '') : '', checkUrl = cCheck >= 0 ? unquote(row.cells[cCheck] || '') : '';
