const groupBlocked = group => `the resource group "${group}" cannot be passed to az by the plugin (${/[()]/.test(group) && process.platform === 'win32' ? 'parentheses are refused by the Windows az.cmd' : 'letters, digits and _ . - ( ) only'})`;
