    let r = await azBusy(['containerapp', 'update', ...inGroup(row), '-n', a.name, '--min-replicas', String(want)], env, true);
    if (r.code === 0) { changed.push(`${a.name} minimum ${a.min} -> ${want}`); r = await tagUpdate(row, env, a.id, 'Delete', [`${MIN_TAG}=${kept}`]); }
