const d = require('../templates/dotnet/workflows/agile-deploy.js');
const { az, cli, azReason, listGroup, groupLive, took, inGroup, waitPause, clock, sleep, json } = d;

const SYSTEM_DBS = ['azure_maintenance', 'azure_sys', 'postgres'];
const DRILL_NAME = /-drill-\d{10}$/;
// ARM's own answer for a server that is not there: `(ResourceNotFound) The Resource '...' under resource group '...' was not found.` (AC11 records the text of a real run).
const NOT_FOUND = /ResourceNotFound|under resource group.*was not found/i;
// `Provisioning` is what a restore in progress reports (measured 2026-10-07); the others are the states Azure documents for a server in transit.
const SETTLING = /^(Provisioning|Creating|Updating|Starting|Stopping|Dropping|Restarting)$/i;
const deleteWait = () => (process.env.AGILE_DRILL_DELETE_WAIT_MS !== undefined ? Number(process.env.AGILE_DRILL_DELETE_WAIT_MS) : 15 * 60 * 1000);
const RULE = 'agile-drill', IPV4 = /^\d{1,3}(\.\d{1,3}){3}$/;   // a firewall rule of a flexible server takes IPv4 addresses only
