  const prefixOf = n => drillName(n).replace(DRILL_NAME, '-drill-');
  const leftover = s => DRILL_NAME.test(s.name) && l.pgs.some(o => o !== s && s.name.startsWith(prefixOf(o.name)));
  const sources = l.pgs.filter(s => !leftover(s)), leftovers = l.pgs.filter(leftover).map(s => s.name);
  // A run that stops must not hide a server that is billed per hour.
  const stopWith = reason => ({ ok: false, reason: leftovers.length ? `${reason}; left over from an earlier drill and billed per hour: ${leftovers.join(', ')} (remove with ${leftovers.map(n => deleteCommand(row, n)).join(' ; ')})` : reason });
  if (!sources.length) return stopWith('restore drill covers PostgreSQL only; Azure SQL is #104');
