  for (const s of sources) {
    const shown = showServer(row, env, s.name);
    if (!shown.ok) return { ok: false, reason: `PostgreSQL ${s.name}: ${shown.reason}` };
    const i = shown.info;
    if (i.state === 'Stopped') return stopWith(`${s.name} is Stopped: run /agile:publish ${environment} --resume first`);
    if (i.state !== 'Ready') return stopWith(`${s.name} is ${i.state}; run the restore drill again when it is Ready`);
    const server = { name: s.name, sku: i.sku, storageGb: i.storageGb, version: i.version, retention: i.retention, earliest: i.earliest ? when(i.earliest) : 'not reported', drill: drillName(s.name) };
    servers.push(server);
    lines.push(`Restore drill ${environment} (aca, ${row.resourceGroup}): PostgreSQL ${s.name}, ${i.sku}, ${i.storageGb} GB, version ${i.version}, backup retention ${i.retention} days, earliest restore point ${server.earliest}`,
      `Would create ${server.drill} (restore to now), billed per hour until removed; the drill removes it`);
  }
  for (const name of leftovers) lines.push(`Left over from an earlier drill: ${name}, billed per hour; the drill removes it first`);
