    // --no-wait: the cap is ours to enforce by asking the server, not by killing an az that may leave its child running.
    const r = az(['postgres', 'flexible-server', 'restore', ...inGroup(row), '--source-server', server.name, '--name', server.drill, '--yes', '--no-wait'], env, undefined, 15 * 60 * 1000);
