      if (!s.ok && s.missing && Date.now() - started < Math.min(limit, 5 * 60 * 1000)) { await sleep(waitPause()); continue; }
      if (!s.ok) { out.reason = `${server.drill}: ${s.reason}`; return out; }
      seen = true;
      state = s.info.state;
      if (state === 'Ready') break;
      if (Date.now() - started >= limit) { out.reason = slow(); return out; }
      await sleep(waitPause());
