    if (diffs.length) { out.reason = `the restored server differs from ${server.name}: ${diffs.join('; ')}`; return out; }
    out.shape.push(`shape: Ready, version ${b.version}, ${b.sku}, ${b.storageGb} GB; databases ${sdb.names.length ? sdb.names.join(', ') : 'none besides Azure\'s'}`);
